import fs from "node:fs";
import path from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";

// The website-to-CRM contract, seen from the CRM. fixtures/website-flight-inquiry-contract.json is generated BY THE WEBSITE'S OWN CODE (its validated-request-to-body builder,
// fixed clock) and a byte-identical copy is committed in the website repository, where a test fails if the website's payload changes without the fixture. Here every
// accepted body goes through the CRM's REAL strict route schema and then through the real createWebsiteFlightLead, and we check what would be STORED. A change to the CRM schema
// that rejects what the website sends, or a change to the website payload that the CRM would reject, therefore fails a test on BOTH sides before release.
//
// To update after an intentional change: regenerate in the website repository (BFT_UPDATE_CONTRACT=1 ... tests/crm-contract-fixtures.spec.ts), copy the file here.

const { leadCreate, leadFindUnique } = vi.hoisted(() => ({ leadCreate: vi.fn(), leadFindUnique: vi.fn() }));

vi.mock("@/lib/prisma", () => ({
  prisma: { lead: { create: leadCreate, findUnique: leadFindUnique }, contact: { findUnique: vi.fn() } },
}));
vi.mock("@/server/contact-resolution", () => ({ resolveContactForNewLead: vi.fn(async () => ({ contactId: "contact-1", isNewContact: true })) }));
vi.mock("@/server/actions/lead-queue", () => ({ distributeNewWebsiteLead: vi.fn(async () => ({ ok: true })) }));
vi.mock("@/server/activity-log", () => ({ logActivity: vi.fn(async () => {}) }));
vi.mock("@/server/queries/reference-data", () => ({ resolveAirportCodes: vi.fn(async () => ({})) }));

import { createWebsiteFlightLead, websiteFlightInquirySchema } from "../lead-intake";

interface AcceptedCase {
  name: string;
  body: Record<string, unknown>;
  expect: { flexibleDates: boolean; dateFlexibilityDays: number | null };
}
interface RejectedCase {
  name: string;
  body: Record<string, unknown>;
  rejectedBecause: string;
}
const fixture = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures", "website-flight-inquiry-contract.json"), "utf8")) as { version: number; accepted: AcceptedCase[]; rejected: RejectedCase[] };

beforeEach(() => {
  vi.clearAllMocks();
  leadFindUnique.mockResolvedValue(null);
  leadCreate.mockResolvedValue({ id: "lead-contract" });
});

describe("the website payload contract (fixtures generated by the website)", () => {
  it("is a version this test understands and covers both directions", () => {
    expect(fixture.version).toBe(1);
    expect(fixture.accepted.length).toBeGreaterThanOrEqual(7);
    expect(fixture.rejected.length).toBeGreaterThanOrEqual(9);
  });

  it.each(fixture.accepted.map((c) => [c.name, c] as const))("accepts what the website sends: %s", async (_name, c) => {
    const parsed = websiteFlightInquirySchema.safeParse(c.body);
    expect(parsed.success, parsed.success ? "" : JSON.stringify(parsed.error.issues.map((i) => ({ path: i.path.join("."), message: i.message })))).toBe(true);
    if (!parsed.success) return;

    // And what would be stored: the same flexibility the website's own fixture says the visitor chose.
    const result = await createWebsiteFlightLead({ data: { ...parsed.data, submissionId: "contract-submission-0001" }, companyId: "company-1", submissionInfo: undefined });
    expect(result).toEqual({ status: "created", id: "lead-contract" });
    const stored = leadCreate.mock.calls[0][0].data;
    expect(stored.flexibleDates).toBe(c.expect.flexibleDates);
    expect(stored.dateFlexibilityDays).toBe(c.expect.dateFlexibilityDays);
    expect(stored.source).toBe("WEBSITE");
  });

  it.each(fixture.rejected.map((c) => [c.name, c] as const))("refuses what the website must never send: %s", (_name, c) => {
    const parsed = websiteFlightInquirySchema.safeParse(c.body);
    expect(parsed.success).toBe(false);
    if (parsed.success) return;
    // It is refused for the reason the fixture names, not by accident for some other field.
    const text = JSON.stringify(parsed.error.issues.map((i) => ({ path: i.path, message: i.message, keys: "keys" in i ? i.keys : undefined })));
    expect(text).toContain(c.rejectedBecause);
  });

  it("the 'exact dates chosen' body keeps meaning exact dates (0 days, not flexible), not 'unknown'", () => {
    const exact = fixture.accepted.find((c) => c.name === "round trip, exact dates chosen");
    expect(exact?.expect).toEqual({ flexibleDates: false, dateFlexibilityDays: 0 });
  });
});
